  where x.lesson_id = l.id and x.part = v.part and x.position = v.position
);

-- 0007_level_teachers.sql
-- One video teacher (an avatar) per level, shown above that level's lessons.
-- Safe to run twice.

create table if not exists level_teachers (
  level text primary key check (level in ('A1', 'A2', 'B1', 'B2', 'C1')),
  name text not null,
  photo_url text,
  intro text,
  intro_az text,
  intro_ru text,
  video_url text,
  updated_at timestamptz not null default now()
);

alter table level_teachers enable row level security;

drop policy if exists "anyone reads level teachers" on level_teachers;
create policy "anyone reads level teachers" on level_teachers for select using (true);

insert into level_teachers (level, name, intro, intro_az, intro_ru) values (
  'A1',
  'Nicole',
  E'Hi! My name is Nicole, and I am your video teacher for A1 English.\n\nI will teach you 12 lessons. We start with the very first steps: "to be", the Present Simple, "a / an / the", plurals and more. I speak slowly and clearly, and I show every rule on the screen with easy examples.\n\nAfter each video, you do two short tests. You can see your mistakes and the right answers. Step by step, you will understand English and speak with more confidence.\n\nDon''t worry about mistakes. Mistakes help us learn! Let''s start together.\n\nSee you in Lesson 1!',
  'Salam! Mən Nicole, A1 səviyyəsi üzrə video müəllimənizəm. 12 dərsdə sizinlə ingilis dilinin ilk addımlarını keçəcəyik. Hər qaydanı ekranda sadə nümunələrlə göstərirəm, hər videodan sonra isə iki qısa test var.',
  'Привет! Я Николь, ваш видеопреподаватель уровня A1. За 12 уроков мы пройдём первые шаги в английском. Каждое правило я показываю на экране с простыми примерами, а после каждого видео вас ждут два коротких теста.'
) on conflict (level) do nothing;

notify pgrst, 'reload schema';

-- 0008_lesson_results.sql
-- Each student's best result per lesson, for the grade and progress on the Lessons page.
-- Safe to run twice.

create table if not exists lesson_results (
  student_id uuid not null references profiles on delete cascade,
  lesson_id int not null references lessons on delete cascade,
  best_right int not null check (best_right >= 0),
  total int not null check (total > 0 and best_right <= total),
  attempts int not null default 1,
  updated_at timestamptz not null default now(),
  primary key (student_id, lesson_id)
);

alter table lesson_results enable row level security;

drop policy if exists "own lesson results" on lesson_results;
create policy "own lesson results" on lesson_results for select using (student_id = auth.uid());

notify pgrst, 'reload schema';

-- 0009_lesson_vocab.sql
-- Vocabulary for every lesson: 20 words and 5 phrasal verbs with Azerbaijani and
-- Russian translations and an example sentence. The [bracketed] part of the example
-- is the gap in the vocabulary test. Readable after the lesson is bought.
-- Generated by supabase/vocab/build.py. Safe to run twice.

create table if not exists lesson_vocab (
  id serial primary key,
  lesson_id int not null references lessons on delete cascade,
  position int not null,
  kind text not null check (kind in ('word', 'phrasal')),
  term text not null,
  az text not null,
  ru text not null,
  example text not null,
  unique (lesson_id, position)
);

alter table lesson_vocab enable row level security;

drop policy if exists "vocab after purchase" on lesson_vocab;
create policy "vocab after purchase" on lesson_vocab for select using (
  exists (select 1 from lesson_purchases p where p.lesson_id = lesson_vocab.lesson_id and p.student_id = auth.uid())
);

