('c1-future-in-past', 25, 'phrasal', 'wipe out', 'məhv etmək', 'уничтожать', 'The disease would [wipe out] half the population.'),
('c1-would-rather', 21, 'phrasal', 'stay in', 'evdə qalmaq', 'оставаться дома', 'I''d rather [stay in] tonight.'),
('c1-would-rather', 22, 'phrasal', 'sit through', 'sona qədər oturmaq (darıxdırıcı)', 'высидеть', 'I''d rather not [sit through] another boring film.'),
('c1-would-rather', 23, 'phrasal', 'splash out', 'çoxlu pul xərcləmək', 'раскошелиться', 'I''d rather [splash out] on a good concert.'),
('c1-would-rather', 24, 'phrasal', 'sleep in', 'gec oyanmaq', 'поспать подольше', 'I''d rather [sleep in] on Sunday.'),
('c1-would-rather', 25, 'phrasal', 'opt for', 'seçmək', 'выбирать', 'I''d [opt for] the cheaper tickets.'),
('c1-nominalisation', 21, 'phrasal', 'level off', 'sabitləşmək', 'стабилизироваться', 'Prices have [levelled off].'),
('c1-nominalisation', 22, 'phrasal', 'bounce back', 'tez bərpa olunmaq', 'восстановиться', 'The economy [bounced back] quickly.'),
('c1-nominalisation', 23, 'phrasal', 'drive up', 'qaldırmaq (qiyməti)', 'взвинчивать', 'High demand [drives up] prices.'),
('c1-nominalisation', 24, 'phrasal', 'scale back', 'kiçiltmək', 'сокращать (масштаб)', 'The firm [scaled back] its plans.'),
('c1-nominalisation', 25, 'phrasal', 'factor in', 'nəzərə almaq', 'учитывать', 'We must [factor in] the cost of transport.')
) as v(slug, position, kind, term, az, ru, example)
join lessons l on l.slug = v.slug
where not exists (
  select 1 from lesson_vocab x where x.lesson_id = l.id and x.position = v.position
);

notify pgrst, 'reload schema';

-- 0010_lesson_videos_bucket.sql
-- Storage for lesson videos shown with the site's own player (no YouTube buttons).
-- The admin uploads from İdarə → Lesson videoları; uploads go through a signed URL
-- made by the server, so no storage policies are needed. Safe to run twice.

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('lesson-videos', 'lesson-videos', true, 52428800, array['video/mp4', 'video/webm', 'video/quicktime'])
on conflict (id) do update
  set public = true,
      file_size_limit = excluded.file_size_limit,
      allowed_mime_types = excluded.allowed_mime_types;

-- 0011_ai_teacher.sql
-- Speaking club: a student talks one-on-one with an AI video teacher on a topic of their level.
-- Run once in Supabase SQL Editor. Safe to run twice.

alter type payment_kind add value if not exists 'ai_chat';

-- One paid AI conversation. Only the server reads and writes it.
create table if not exists ai_chats (
  id uuid primary key default gen_random_uuid(),
  student_id uuid not null references profiles on delete cascade,
  topic_id int not null references practice_topics,
  level cefr_level not null,
  minutes int not null check (minutes in (15, 30, 60)),
  paid boolean not null default false,
  -- Seconds of conversation already used; the rest can be used after a dropped connection.
  used_seconds int not null default 0,
  started_at timestamptz,
  liveavatar_session_id text,
  ended_at timestamptz,
  created_at timestamptz not null default now()
);
create index if not exists ai_chats_student on ai_chats (student_id, created_at desc);

alter table ai_chats enable row level security;

notify pgrst, 'reload schema';
